+      lines.push(`- Aliases: ${note.aliases.join(", ") || "(none)"}`);
+      lines.push(`- Code links: ${note.codeLinks.join(", ") || "(none)"}`);
+      lines.push(`- Note links: ${note.noteLinks.join(", ") || "(none)"}`);
+      lines.push("");
+      lines.push("##### Summary");
+      lines.push(note.summary);
