+function defaultOutputPath(
+  workspaceRoot: string,
+  profileName: string,
+  format: CxNotesExtractFormat,
+): string {
+  const extension =
+    format === "markdown" ? "md" : format === "xml" ? "xml" : "txt";
+  return path.join(
+    workspaceRoot,
+    "dist",
+    `notes-${profileName}.llm.${extension}`,
+  );
+}
